$tempBase=[IO.Path]::GetFullPath([IO.Path]::GetTempPath());$isolatedRoot=Join-Path $tempBase ('maya-canonical-negative-matrix-'+[guid]::NewGuid().ToString('N'));$qaRuns=Join-Path $isolatedRoot 'QA\TestRuns';$qaFixtures=Join-Path $isolatedRoot 'QA\Fixtures';$fixturePath=Join-Path $qaFixtures 'CreatePlanViewsEmpty.rvt'
