if($caseNumbers.Count -ne 27 -or @($caseNumbers|Sort-Object -Unique).Count -ne 27 -or @($caseNumbers|Where-Object {$_ -in 8,9,11,25,26,27}).Count){throw 'Executable matrix case set is invalid.'}
Write-Host ('ExecutableCaseNumbers = '+($caseNumbers -join ','));Write-Host "ExecutableCaseCount = $($caseNumbers.Count)";Write-Host 'RemovedCasesPresentInExecutableSet = '
function Invoke-AuthoritativeTaskMutation([string]$StoreRoot,[string]$TaskId,[scriptblock]$Transform){Invoke-RepatoStoreMutation $StoreRoot {param($d,$p)$t=Find-RepatoTask $d $TaskId;&$Transform $t;$t}|Out-Null;Find-RepatoTask (Read-RepatoTaskStore $StoreRoot) $TaskId}
function Invoke-AuthoritativeWorkflowMutation([string]$StoreRoot,[string]$TaskId,[string]$WorkflowId,[scriptblock]$Transform){$d=Read-RepatoTaskStore $StoreRoot;$t=Find-RepatoTask $d $TaskId;$w=Get-DeployWorkflow $StoreRoot $TaskId $WorkflowId;Invoke-RepatoWorkflowMutation $StoreRoot $TaskId $WorkflowId $w.workflowRevision $t.revision $Transform|Out-Null;Get-DeployWorkflow $StoreRoot $TaskId $WorkflowId}
function New-Baseline{
 $s=Join-Path ([IO.Path]::GetTempPath()) ('neg-'+[guid]::NewGuid().ToString('N'));$f=Join-Path ([IO.Path]::GetTempPath()) ('negf-'+[guid]::NewGuid().ToString('N'));$qaAddin=Join-Path $f 'RepatoQA';New-Item $qaAddin -ItemType Directory -Force|Out-Null
 $c=Join-Path $f 'a.dll';$m=Join-Path $f 'm.addin';$r=Join-Path $f 'Repato.CreatePlanViews.TestRunner.addin';$p=Join-Path $f 'policy.json';Set-Content $c c;Set-Content $m m;Set-Content $r r;Set-Content $p '{}';$h={param($x)(Get-FileHash $x -Algorithm SHA256).Hash}
 $b=New-MayaQaBootstrap -StoreRoot $s -QaWorkflowId create-plan-views-v1 -RunId ('n-'+[guid]::NewGuid().ToString('N'));$d=Read-RepatoTaskStore $s;$t=Find-RepatoTask $d $b.TaskId;$w=Get-DeployWorkflow $s $b.TaskId $b.WorkflowId;$q='create-plan-views-v1';New-MayaQaBuildRequest -StoreRoot $s -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId $q -UserRequest 'Create Plan Views' -SourceBranch synthetic -ProjectPath synthetic.csproj|Out-Null
 $d=Read-RepatoTaskStore $s;$t=Find-RepatoTask $d $b.TaskId;$w=Get-DeployWorkflow $s $b.TaskId $b.WorkflowId;$e=[pscustomobject]@{BuildRequestId=$w.qaBuildRequest.BuildRequestId;ArtifactPath=$c;ArtifactSha256=&$h $c;ManifestPath=$m;ManifestSha256=&$h $m;BuildStatus='succeeded';SourceCommit='synthetic';EvidenceSource='Synthetic';CandidateDirectory=$f;CandidateSourceCommit='synthetic';QaWorkflowId=$q;RunnerManifestPath=$r;RunnerManifestSha256=&$h $r;DeployedRunnerManifestPath=$r;DeployedRunnerManifestSha256=&$h $r;ValidatedRunnerManifestPath=$r;ValidatedRunnerManifestSha256=&$h $r;QaAddinRoot=$qaAddin;Isolation=[pscustomobject]@{PolicyPath=$p;PolicySha256=&$h $p;Allowed=$true}}
 Invoke-AuthoritativeWorkflowMutation $s $b.TaskId $b.WorkflowId {param($x)$x|Add-Member qaBuildStatus succeeded -Force;$x|Add-Member qaBuildEvidence $e -Force}|Out-Null
 $prepRoot=Join-Path $qaRuns ('synthetic-prep-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $prepRoot|Out-Null;$prepAttempt=[guid]::NewGuid().ToString('N');$prepRun=[guid]::NewGuid().ToString('N');$prepModel=Join-Path $prepRoot 'model.rvt';$prepRequestPath=Join-Path $prepRoot ('tara-'+$prepAttempt+'.request.json');$prepResultPath=$prepRequestPath+'.preparation.json';$fixtureHash=(Get-FileHash $fixturePath).Hash;Copy-Item -LiteralPath $fixturePath -Destination $prepModel;$prepModelHash=(Get-FileHash $prepModel).Hash
 [ordered]@{schemaVersion=1;operation='prepare-disposable-create-plan-views-fixture';requestId=[guid]::NewGuid().ToString('N');taskId=$b.TaskId;workflowId=$b.WorkflowId;attemptId=$prepAttempt;runId=$prepRun;requestPath=$prepRequestPath;modelPath=$prepModel;modelSha256=$fixtureHash;outputPath=$prepResultPath}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $prepRequestPath -Encoding UTF8
 [ordered]@{Status='Passed';Operation='prepare-disposable-create-plan-views-fixture';TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;AttemptId=$prepAttempt;RunId=$prepRun;ModelPath=$prepModel;SourceModelSha256=$fixtureHash;PreparedModelSha256=$prepModelHash}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $prepResultPath -Encoding UTF8
 Invoke-AuthoritativeTaskMutation $s $b.TaskId {param($x)$x.status='in-progress';$x.workflowStage='build-checks';$x.approvalRequests=[object[]]@()}|Out-Null
 Invoke-AuthoritativeWorkflowMutation $s $b.TaskId $b.WorkflowId {param($x)$x.qaRunId=$null}|Out-Null
 $run=New-MayaQaRun $s $b.TaskId $b.WorkflowId $q $prepRun -FixturePreparationResultPath $prepResultPath
 $tw=Get-DeployWorkflow $s $b.TaskId $b.WorkflowId;$tt=Find-RepatoTask (Read-RepatoTaskStore $s) $b.TaskId
 Update-RepatoTask $s $b.TaskId in-progress qa Maya $null $null -ExpectedTaskRevision $tt.revision -ExpectedWorkflowId $b.WorkflowId -ExpectedWorkflowRevision $tw.workflowRevision -ExpectedQaWorkflowId $q|Out-Null
 Update-RepatoTask $s $b.TaskId passed qa Tara $null $null|Out-Null;Request-RepatoTaskApproval $s $b.TaskId qa-run maya|Out-Null;Resolve-RepatoTaskApproval $s $b.TaskId approve Maya synthetic|Out-Null
 $hnd=New-MayaQaCanonicalPreparation $s $b.TaskId $b.WorkflowId $q
 [pscustomobject]@{Store=$s;Files=$f;TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;QaWorkflowId=$q;RunId=$run.RunId;Handoff=$hnd.Handoff;FixturePreparationEvidence=$((Find-RepatoTask (Read-RepatoTaskStore $s) $b.TaskId).mayaTaraQaPacket.FixturePreparationEvidence);RunRoot=(Join-Path $qaRuns ($b.WorkflowId+'-'+$run.RunId));PrepRoot=$prepRoot}
}
function Remove-Fallback($task,[string]$name){foreach($o in @($task.mayaTaraQaPacket,$task.mayaTaraQaPacket.Handoff)){if($o -and $o.PSObject.Properties.Name -contains $name){$o.PSObject.Properties.Remove($name)}}}
function Invoke-LaunchPreparationNegativeCase([int]$n){
 $b=New-Baseline;if($b.FixturePreparationEvidence.PSObject.Properties['ExpiresUtc']){throw 'Fixture preparation expiry regression case unexpectedly includes ExpiresUtc.'};$native=$false;$actual=$null;$expected=if($n -eq 17){'Canonical IsolationPolicyPath hash validation failed'}else{'Canonical RunnerManifestPath hash validation failed'};$created=$false;$claimedOk=$false;$verified=$false
 try{$d=Read-RepatoTaskStore $b.Store;$t=Find-RepatoTask $d $b.TaskId;$p=$t.mayaTaraQaPacket;$w=Get-DeployWorkflow $b.Store $b.TaskId $b.WorkflowId;$e=$w.qaBuildEvidence
  $resolved=Resolve-MayaQaTaskStoreIdentity $b.Store $b.TaskId $b.WorkflowId $b.QaWorkflowId;if(@($resolved.Errors).Count){throw (@($resolved.Errors)-join '; ')};$attempt=$t.mayaTaraAttempt;$pre=[pscustomobject]@{TaskId=$resolved.SelectedTaskId;WorkflowId=$resolved.SelectedWorkflowId;QaWorkflowId=$resolved.SelectedQaWorkflowId;TestId=$b.Handoff.NativeTestId;HandoffId=$resolved.SelectedHandoffId;AttemptId=$resolved.SelectedAttemptId;RunId=$resolved.SelectedRunId;ArtifactPath=$e.ArtifactPath;ArtifactSha256=$e.ArtifactSha256;RunnerManifest=$e.RunnerManifestPath;ValidatedRunnerManifestPath=$e.ValidatedRunnerManifestPath;RunnerManifestSha256=$e.RunnerManifestSha256;ValidatedRunnerManifestSha256=$e.ValidatedRunnerManifestSha256;FixturePath=$p.FixturePath;FixtureSha256=$p.FixtureSha256;DisposableFixturePath=$p.ModelPath;DisposableFixtureSha256=(Get-FileHash $p.ModelPath).Hash;FixturePreparationEvidence=$p.FixturePreparationEvidence;Isolation=$e.Isolation;RuntimeRoot=$attempt.RuntimeRoot;RequestExpiresUtc=$attempt.RequestExpiresUtc};if($pre.HandoffId -ne $resolved.SelectedHandoffId -or $pre.AttemptId -ne $attempt.AttemptId -or $pre.RunId -ne $attempt.RunId){throw 'Authoritative preflight identity mismatch.'}
  $execution=New-MayaQaExecutionRecord $b.Store $b.TaskId $pre;$created=$true;$claimed=Claim-MayaQaExecutionRecord $b.Store $b.TaskId Tara $execution;$claimId=$claimed.ClaimId;$claimedOk=![string]::IsNullOrWhiteSpace($claimId)
  Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)if($n -eq 12){$x.mayaTaraExecution.RunnerManifestPath=Join-Path $b.Files 'missing.addin'}elseif($n -eq 13){$x.mayaTaraExecution.RunnerManifestSha256='0'*64}else{$x.mayaTaraExecution.IsolationPolicySha256='0'*64}}|Out-Null
  $re=Find-RepatoTask (Read-RepatoTaskStore $b.Store) $b.TaskId;$verified=if($n -eq 12){$re.mayaTaraExecution.RunnerManifestPath -like '*missing.addin'}elseif($n -eq 13){$re.mayaTaraExecution.RunnerManifestSha256 -eq ('0'*64)}else{$re.mayaTaraExecution.IsolationPolicySha256 -eq ('0'*64)}
  try{Prepare-MayaQaCanonicalNativeLaunch $b.Store $b.TaskId $claimId $b.Files -QaAddinRoot $b.Files -DryRun|Out-Null;throw 'MATRIX_NO_REJECTION'}catch{$actual=$_.Exception.Message}
 }catch{$actual=$_.Exception.Message}
 $matched=(!$native -and $actual -match $expected);[pscustomobject]@{CaseNumber=$n;Mutation="case $n";AuthoritativeMutationVerified=$verified;ProductionBoundary='Prepare-MayaQaCanonicalNativeLaunch';ExpectedRejection=$expected;ActualExceptionType=if($actual){$actual.GetType().FullName};ActualExceptionMessage=$actual;ExpectedProductionRejectionMatched=$matched;NativeBoundaryReached=$native;Passed=($created -and $claimedOk -and $verified -and $matched);FailureReason=if(!$created -or !$claimedOk){'execution lifecycle setup failed'}elseif(!$verified){'mutation not persisted'}elseif(!$matched){'wrong rejection'}else{$null}}
 Remove-Item $b.Store,$b.Files,$b.RunRoot,$b.PrepRoot -Recurse -Force -ErrorAction SilentlyContinue
}
function Invoke-Case([int]$n){
 $b=New-Baseline;$native=$false;$verified=$false;$setup=$false;$boundary='Invoke-MayaQaCanonicalTransaction';$expected='';$actual=$null
 try{$d=Read-RepatoTaskStore $b.Store;$t=Find-RepatoTask $d $b.TaskId;$p=$t.mayaTaraQaPacket;$w=Get-DeployWorkflow $b.Store $b.TaskId $b.WorkflowId;$e=$w.qaBuildEvidence;$req=[pscustomobject]@{Stage='handoff-ready';TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;QaWorkflowId=$b.QaWorkflowId;RunId=$b.RunId;Handoff=$b.Handoff}
 switch($n){
  1{Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraQaPacket.PSObject.Properties.Remove('FixturePath')}|Out-Null;$expected='FixturePath'}
  2{Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraQaPacket.PSObject.Properties.Remove('FixtureSha256')}|Out-Null;Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.PSObject.Properties.Remove('qaFixtureSha256')}|Out-Null;$expected='FixtureSha256'}
  3{Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraQaPacket.FixtureSha256='bad'}|Out-Null;$expected='source fixture or disposable model hash'}
  4{Remove-Item $p.ModelPath -Force;$expected='DisposableFixtureSha256'}
  5{Set-Content $p.ModelPath tampered;$expected='fixture preparation identity/model hash'}
  6{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.PSObject.Properties.Remove('RunnerManifestPath')}|Out-Null;Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)Remove-Fallback $x 'RunnerManifestPath'}|Out-Null;$req.Handoff.RunnerManifestPath=$null;$req.Handoff.PSObject.Properties.Remove('RunnerManifestPath');$expected='RunnerManifest'}
  7{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.PSObject.Properties.Remove('RunnerManifestSha256')}|Out-Null;Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)Remove-Fallback $x 'RunnerManifestSha256'}|Out-Null;$req.Handoff.RunnerManifestSha256=$null;$req.Handoff.PSObject.Properties.Remove('RunnerManifestSha256');$expected='RunnerManifestSha256'}
  10{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.ValidatedRunnerManifestPath=(Join-Path $b.Files 'other.addin')}|Out-Null;$expected='runner-manifest path contract mismatch'}
  14{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.PSObject.Properties.Remove('Isolation')}|Out-Null;$req.Handoff.Isolation=$null;$req.Handoff.PSObject.Properties.Remove('Isolation');$expected='Isolation'}
  15{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.Isolation.PSObject.Properties.Remove('PolicyPath')}|Out-Null;$req.Handoff.Isolation=$null;$req.Handoff.PSObject.Properties.Remove('Isolation');$expected='PolicyPath'}
  16{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.Isolation.PSObject.Properties.Remove('PolicySha256')}|Out-Null;$req.Handoff.Isolation=$null;$req.Handoff.PSObject.Properties.Remove('Isolation');$expected='PolicySha256'}
  18{Invoke-AuthoritativeWorkflowMutation $b.Store $b.TaskId $b.WorkflowId {param($x)$x.qaBuildEvidence.Isolation.Allowed=$false}|Out-Null;$expected='Isolation.Allowed'}
  19{$req.QaWorkflowId=$null;$expected='QaWorkflowId'}20{$req.QaWorkflowId='wrong';$expected='QaWorkflowId'}21{$req.WorkflowId=$null;$expected='WorkflowId'}22{$req.WorkflowId='wrong';$expected='WorkflowId'}23{$req.RunId=$null;$expected='RunId'}24{$req.RunId='wrong';$expected='RunId'}28{$t.mayaTaraAttempt.RequestExpiresUtc='bad';$expected='DateTime'}29{$t.mayaTaraAttempt.RequestExpiresUtc=(Get-Date).ToUniversalTime().AddMinutes(-1).ToString('O');$expected='expired'}30{$t.mayaTaraAttempt.RuntimeRoot=$b.Files+'\unsafe';$expected='RuntimeRoot'}31{$t.PSObject.Properties.Remove('mayaTaraAttempt');$expected='persisted attempt'}32{$t.mayaTaraAttempt=$null;$expected='persisted attempt'}33{$t.mayaTaraAttempt=[pscustomobject]@{Legacy=$true};$expected='persisted attempt'}
  default{$setup=$true;try{Invoke-MayaQaCanonicalTransaction $b.Store 'Create Plan Views' -RequestInvoker {param($s,$u,$br,$pr)$req} -NativeCoreInvoker {param($s,$id,$claim)$native=$true;throw 'MATRIX_NATIVE_SENTINEL'}|Out-Null;throw 'MATRIX_NO_REJECTION'}catch{$actual=$_.Exception.Message};$verified=$true}
 }
 if($n -eq 28){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraAttempt.RequestExpiresUtc='bad'}|Out-Null}
 if($n -eq 29){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraAttempt.RequestExpiresUtc=(Get-Date).ToUniversalTime().AddMinutes(-1).ToString('O')}|Out-Null}
 if($n -eq 30){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraAttempt.RuntimeRoot=(Join-Path $b.Files 'unsafe')}|Out-Null}
 if($n -eq 31){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.PSObject.Properties.Remove('mayaTaraAttempt')}|Out-Null}
 if($n -eq 32){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraAttempt=$null}|Out-Null}
 if($n -eq 33){Invoke-AuthoritativeTaskMutation $b.Store $b.TaskId {param($x)$x.mayaTaraAttempt=[pscustomobject]@{Legacy=$true}}|Out-Null}
 if($n -notin 12,13,17){try{Invoke-MayaQaCanonicalTransaction $b.Store 'Create Plan Views' -RequestInvoker {param($s,$u,$br,$pr)$req} -NativeCoreInvoker {param($s,$id,$claim)$native=$true;throw 'MATRIX_NATIVE_SENTINEL'}|Out-Null;throw 'MATRIX_NO_REJECTION'}catch{$actual=$_.Exception.Message};$setup=$true;$verified=$true}
 }catch{$actual=$_.Exception.Message}
 $matched=(!$native -and $actual -and $actual -match $expected);[pscustomobject]@{CaseNumber=$n;Mutation="case $n";AuthoritativeMutationVerified=$verified;ProductionBoundary=$boundary;ExpectedRejection=$expected;ActualExceptionType=if($actual){$actual.GetType().FullName};ActualExceptionMessage=$actual;ExpectedProductionRejectionMatched=$matched;NativeBoundaryReached=$native;Passed=($setup -and $verified -and $matched);FailureReason=if(!$setup){'HARNESS_SETUP_FAILURE'}elseif($native){'native sentinel reached'}elseif(!$matched){'wrong rejection'}else{$null}}
 Remove-Item $b.Store,$b.Files,$b.RunRoot,$b.PrepRoot -Recurse -Force -ErrorAction SilentlyContinue
}
$results=@($caseNumbers|ForEach-Object {Write-Host ("CASE $_ START");$result=if($_ -in 12,13,17){Invoke-LaunchPreparationNegativeCase $_}else{Invoke-Case $_};Write-Host ("CASE $_ END Passed="+$result.Passed);$result});$results|ConvertTo-Json -Depth 8;$failed=@($results|Where-Object {-not $_.Passed}).Count -gt 0;if([IO.Path]::GetFullPath($isolatedRoot).StartsWith($tempBase,[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $isolatedRoot)){Remove-Item -LiteralPath $isolatedRoot -Recurse -Force};if($failed){exit 1}
